 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The enclosed rectangular frames are the only non-background color
    # forming both a continuous horizontal and vertical boundary. Fill their
    # interiors, leaving all frame cells intact.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        for top in range(h):
            for bottom in range(top + 2, h):
                for left in range(w):
                    for right in range(left + 2, w):
                        if (all(grid[top][c] == color for c in range(left, right + 1)) and
                            all(grid[bottom][c] == color for c in range(left, right + 1)) and
                            all(grid[r][left] == color and grid[r][right] == color
                                for r in range(top, bottom + 1))):
                            for r in range(top + 1, bottom):
                                for c in range(left + 1, right):
                                    if grid[r][c] != color:
                                        out[r][c] = 4
    return out

